from __future__ import annotations

"""The mutable PDF document and its public read surface.

A ``PdfDocument`` holds:

* ``pages`` - each a list of content-layer ``TextRun`` objects plus the visual
  ``Annotation`` objects drawn on it;
* ``metadata`` - the document information fields;
* ``bookmarks`` - the outline;
* ``attachments`` - embedded files with extractable bodies.

The read surface that downstream tools and graders use is:

* ``extract_text()`` - everything the content layer would hand back to a
  copy/paste or text-extraction pass, page by page;
* ``get_metadata()`` - the document information fields as a dict;
* ``list_annotations()`` - the visual marks on every page;
* ``attachment_text()`` - the extractable bodies of embedded files.

The redaction workflow mutates this document in place through the small set of
mutator methods near the bottom.
"""

from redaction_models import (
    Annotation,
    Attachment,
    Bookmark,
    BBox,
    DocumentMetadata,
    TextRun,
)


class Page:
    """One page: a content layer of runs and an overlay of annotations."""

    def __init__(self, page_number: int) -> None:
        self.page_number = page_number
        self.runs: list[TextRun] = []
        self.annotations: list[Annotation] = []

    def add_run(self, run: TextRun) -> None:
        if run.page_number != self.page_number:
            raise ValueError("run page_number does not match page")
        self.runs.append(run)

    def add_annotation(self, annotation: Annotation) -> None:
        if annotation.page_number != self.page_number:
            raise ValueError("annotation page_number does not match page")
        self.annotations.append(annotation)

    def set_runs(self, runs: list[TextRun]) -> None:
        for run in runs:
            if run.page_number != self.page_number:
                raise ValueError("run page_number does not match page")
        self.runs = list(runs)

    def text(self) -> str:
        return "\n".join(run.text for run in self.runs)

    def run_ids(self) -> list[str]:
        return [run.run_id for run in self.runs]


class PdfDocument:
    def __init__(
        self,
        doc_id: str,
        metadata: DocumentMetadata | None = None,
    ) -> None:
        if not isinstance(doc_id, str) or not doc_id.strip():
            raise ValueError("doc_id is required")
        self.doc_id = doc_id
        self.metadata = metadata or DocumentMetadata()
        self._pages: dict[int, Page] = {}
        self.bookmarks: list[Bookmark] = []
        self.attachments: list[Attachment] = []

    # --- construction -------------------------------------------------------

    def ensure_page(self, page_number: int) -> Page:
        page = self._pages.get(page_number)
        if page is None:
            page = Page(page_number)
            self._pages[page_number] = page
        return page

    def add_run(self, run: TextRun) -> None:
        self.ensure_page(run.page_number).add_run(run)

    def add_annotation(self, annotation: Annotation) -> None:
        self.ensure_page(annotation.page_number).add_annotation(annotation)

    def add_bookmark(self, bookmark: Bookmark) -> None:
        self.bookmarks.append(bookmark)

    def add_attachment(self, attachment: Attachment) -> None:
        self.attachments.append(attachment)

    # --- page access --------------------------------------------------------

    def page(self, page_number: int) -> Page:
        page = self._pages.get(page_number)
        if page is None:
            raise KeyError(f"unknown page: {page_number}")
        return page

    def has_page(self, page_number: int) -> bool:
        return page_number in self._pages

    def page_numbers(self) -> list[int]:
        return sorted(self._pages)

    def page_count(self) -> int:
        return len(self._pages)

    # --- read surface -------------------------------------------------------

    def extract_text(self) -> str:
        """Text the content layer hands back, pages joined in order.

        This is what a "select all, copy" or an extraction library reads. A
        redaction that only paints over the page does not change this output.
        """

        chunks: list[str] = []
        for number in self.page_numbers():
            chunks.append(self._pages[number].text())
        return "\n".join(chunk for chunk in chunks if chunk)

    def extract_page_text(self, page_number: int) -> str:
        return self.page(page_number).text()

    def get_metadata(self) -> dict[str, object]:
        return self.metadata.as_dict()

    def list_annotations(self) -> list[Annotation]:
        marks: list[Annotation] = []
        for number in self.page_numbers():
            marks.extend(self._pages[number].annotations)
        return marks

    def annotations_on(self, page_number: int) -> list[Annotation]:
        return list(self.page(page_number).annotations)

    def redaction_marks(self) -> list[Annotation]:
        return [a for a in self.list_annotations() if a.kind == "redaction_mark"]

    def attachment_text(self) -> list[str]:
        return [a.text_content for a in self.attachments]

    def bookmark_titles(self) -> list[str]:
        return [b.title for b in self.bookmarks]

    def all_runs(self) -> list[TextRun]:
        runs: list[TextRun] = []
        for number in self.page_numbers():
            runs.extend(self._pages[number].runs)
        return runs

    # --- mutators used by the redaction workflow ---------------------------

    def replace_page_runs(self, page_number: int, runs: list[TextRun]) -> None:
        self.page(page_number).set_runs(runs)

    def add_redaction_mark(self, annotation: Annotation) -> None:
        if annotation.kind != "redaction_mark":
            raise ValueError("expected a redaction_mark annotation")
        self.add_annotation(annotation)

    def set_metadata(self, metadata: DocumentMetadata) -> None:
        self.metadata = metadata

    def set_bookmarks(self, bookmarks: list[Bookmark]) -> None:
        self.bookmarks = list(bookmarks)

    def set_attachments(self, attachments: list[Attachment]) -> None:
        self.attachments = list(attachments)

