from __future__ import annotations

"""Scrub sensitive strings out of the off-page copies.

The page is not the only place a secret lives. The same string is routinely
copied into the document title, the author or subject field, the keyword list,
bookmark titles, and the bodies of embedded attachments. True redaction has to
remove it from all of them, not only the visible page.

Each helper takes the list of strings a redaction removed and returns a cleaned
copy of the field along with a count of how many fields it changed.
"""

from redaction_models import Attachment, Bookmark, DocumentMetadata


def _strip_secrets(value: str, secrets: list[str]) -> str:
    cleaned = value
    for secret in secrets:
        if not secret:
            continue
        cleaned = cleaned.replace(secret, "")
    return cleaned


def scrub_text(value: str, secrets: list[str]) -> str:
    return _strip_secrets(value, secrets)


def scrub_metadata(
    metadata: DocumentMetadata, secrets: list[str]
) -> tuple[DocumentMetadata, int]:
    """Return cleaned metadata and the number of fields that changed."""

    changed = 0

    new_title = _strip_secrets(metadata.title, secrets)
    if new_title != metadata.title:
        changed += 1

    new_author = _strip_secrets(metadata.author, secrets)
    if new_author != metadata.author:
        changed += 1

    new_subject = _strip_secrets(metadata.subject, secrets)
    if new_subject != metadata.subject:
        changed += 1

    new_keywords: list[str] = []
    for kw in metadata.keywords:
        cleaned = _strip_secrets(kw, secrets)
        if cleaned != kw:
            changed += 1
        if cleaned.strip():
            new_keywords.append(cleaned)
        elif kw.strip() == "":
            new_keywords.append(cleaned)

    cleaned_metadata = DocumentMetadata(
        title=new_title,
        author=new_author,
        subject=new_subject,
        keywords=tuple(new_keywords),
    )
    return cleaned_metadata, changed


def scrub_bookmarks(
    bookmarks: list[Bookmark], secrets: list[str]
) -> tuple[list[Bookmark], int]:
    """Return cleaned bookmarks and the number whose title changed."""

    cleaned: list[Bookmark] = []
    changed = 0
    for bookmark in bookmarks:
        new_title = _strip_secrets(bookmark.title, secrets)
        if new_title != bookmark.title:
            changed += 1
        if new_title.strip():
            cleaned.append(Bookmark(title=new_title, page_number=bookmark.page_number))
        # A bookmark whose entire title was a secret is dropped from the outline.
    return cleaned, changed


def scrub_attachments(
    attachments: list[Attachment], secrets: list[str]
) -> tuple[list[Attachment], int]:
    """Return cleaned attachments and the number whose body changed."""

    cleaned: list[Attachment] = []
    changed = 0
    for attachment in attachments:
        new_body = _strip_secrets(attachment.text_content, secrets)
        if new_body != attachment.text_content:
            changed += 1
        cleaned.append(Attachment(name=attachment.name, text_content=new_body))
    return cleaned, changed

