from dataclasses import dataclass, field, replace


ANNOTATION_KINDS = ("highlight", "note", "redaction_mark")


def _require_text(value: str, field_name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} is required")


def _require_number(value: float, field_name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{field_name} must be a number")


@dataclass(frozen=True)
class BBox:
    """An axis-aligned rectangle in page coordinates.

    ``x0, y0`` is the lower-left corner, ``x1, y1`` the upper-right. The origin
    sits at the bottom-left of the page, which is the PDF user-space convention.
    """

    x0: float
    y0: float
    x1: float
    y1: float

    def __post_init__(self) -> None:
        for name in ("x0", "y0", "x1", "y1"):
            _require_number(getattr(self, name), name)
        if self.x1 < self.x0:
            raise ValueError("x1 must be >= x0")
        if self.y1 < self.y0:
            raise ValueError("y1 must be >= y0")

    def width(self) -> float:
        return self.x1 - self.x0

    def height(self) -> float:
        return self.y1 - self.y0

    def as_tuple(self) -> tuple[float, float, float, float]:
        return (self.x0, self.y0, self.x1, self.y1)


@dataclass(frozen=True)
class TextRun:
    """A run of text painted at a position in the content layer.

    ``box`` is the bounding rectangle the glyphs occupy. ``text`` is laid out
    left to right across ``box`` with each character taking an equal slice of
    the width, which is enough to decide which characters a vertical cut covers.
    """

    run_id: str
    text: str
    box: BBox
    page_number: int

    def __post_init__(self) -> None:
        _require_text(self.run_id, "run_id")
        if not isinstance(self.text, str):
            raise ValueError("text must be a string")
        if not isinstance(self.box, BBox):
            raise ValueError("box must be a BBox")
        if isinstance(self.page_number, bool) or not isinstance(self.page_number, int):
            raise ValueError("page_number must be an int")
        if self.page_number < 0:
            raise ValueError("page_number must be non-negative")

    def char_count(self) -> int:
        return len(self.text)

    def char_width(self) -> float:
        if not self.text:
            return 0.0
        return self.box.width() / len(self.text)

    def char_box(self, index: int) -> BBox:
        """The bounding box of the character at ``index`` within this run."""

        if index < 0 or index >= len(self.text):
            raise IndexError("character index out of range")
        cw = self.char_width()
        left = self.box.x0 + cw * index
        return BBox(left, self.box.y0, left + cw, self.box.y1)

    def with_text(self, text: str, box: BBox, run_id: str | None = None) -> "TextRun":
        return replace(self, text=text, box=box, run_id=run_id or self.run_id)


@dataclass(frozen=True)
class Annotation:
    """A visual mark drawn over a page region."""

    annotation_id: str
    kind: str
    box: BBox
    page_number: int
    label: str = ""

    def __post_init__(self) -> None:
        _require_text(self.annotation_id, "annotation_id")
        if self.kind not in ANNOTATION_KINDS:
            raise ValueError(f"unsupported annotation kind: {self.kind}")
        if not isinstance(self.box, BBox):
            raise ValueError("box must be a BBox")
        if isinstance(self.page_number, bool) or not isinstance(self.page_number, int):
            raise ValueError("page_number must be an int")


@dataclass(frozen=True)
class Bookmark:
    """An outline entry. Titles often echo headings from the page text."""

    title: str
    page_number: int

    def __post_init__(self) -> None:
        _require_text(self.title, "title")
        if isinstance(self.page_number, bool) or not isinstance(self.page_number, int):
            raise ValueError("page_number must be an int")


@dataclass(frozen=True)
class Attachment:
    """An embedded file. ``text_content`` is the extractable body of the file."""

    name: str
    text_content: str

    def __post_init__(self) -> None:
        _require_text(self.name, "name")
        if not isinstance(self.text_content, str):
            raise ValueError("text_content must be a string")


@dataclass(frozen=True)
class DocumentMetadata:
    """Document information dictionary fields that travel with the file."""

    title: str = ""
    author: str = ""
    subject: str = ""
    keywords: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        for name in ("title", "author", "subject"):
            if not isinstance(getattr(self, name), str):
                raise ValueError(f"{name} must be a string")
        for kw in self.keywords:
            if not isinstance(kw, str):
                raise ValueError("keywords must be strings")

    def as_dict(self) -> dict[str, object]:
        return {
            "title": self.title,
            "author": self.author,
            "subject": self.subject,
            "keywords": list(self.keywords),
        }


@dataclass(frozen=True)
class RedactionRegion:
    """A rectangle on one page whose covered content must be removed."""

    page_number: int
    box: BBox

    def __post_init__(self) -> None:
        if isinstance(self.page_number, bool) or not isinstance(self.page_number, int):
            raise ValueError("page_number must be an int")
        if self.page_number < 0:
            raise ValueError("page_number must be non-negative")
        if not isinstance(self.box, BBox):
            raise ValueError("box must be a BBox")


@dataclass
class RedactionResult:
    """Outcome of one ``redact`` pass.

    ``runs_removed`` and ``runs_split`` count content-layer edits; ``marks_added``
    counts the black boxes drawn; ``metadata_scrubbed`` and ``attachments_scrubbed``
    count the off-page copies cleaned.
    """

    regions_applied: int
    runs_removed: int = 0
    runs_split: int = 0
    marks_added: int = 0
    metadata_scrubbed: int = 0
    bookmarks_scrubbed: int = 0
    attachments_scrubbed: int = 0
    details: dict = field(default_factory=dict)

    def total_content_edits(self) -> int:
        return self.runs_removed + self.runs_split


def build_box(x0: float, y0: float, x1: float, y1: float) -> BBox:
    return BBox(x0=x0, y0=y0, x1=x1, y1=y1)


def build_run(run_id: str, text: str, page_number: int, box: BBox) -> TextRun:
    return TextRun(run_id=run_id, text=text, box=box, page_number=page_number)

