from __future__ import annotations

"""Policy: what each region removes, and which off-page copies must follow.

Two questions live here:

* Which content-layer runs does a region touch on its page? The workflow needs
  this to know what to edit.
* What sensitive strings does a region remove from the page? Those same strings
  often sit in metadata, bookmark titles, and attachment bodies, so the scrub
  layer cleans every copy it can find.

The policy reads geometry; it does not mutate the document.
"""

from geometry import boxes_overlap, covered_char_indices
from redaction_models import RedactionRegion, TextRun
from text_layer import covered_text_for_region


def runs_touched_by_region(runs: list[TextRun], region: RedactionRegion) -> list[TextRun]:
    """Runs on the region's page whose box shares area with the region."""

    touched: list[TextRun] = []
    for run in runs:
        if run.page_number != region.page_number:
            continue
        if boxes_overlap(run.box, region.box):
            touched.append(run)
    return touched


def covered_strings_for_region(
    runs: list[TextRun], region: RedactionRegion
) -> list[str]:
    """Distinct, stripped strings the region removes from the page.

    A region that clips the middle of "Account 4019-5567" produces the covered
    substring, which is what we hunt for in metadata and attachments.
    """

    covered: list[str] = []
    for run in runs:
        if run.page_number != region.page_number:
            continue
        indices = covered_char_indices(run, region.box)
        if not indices:
            continue
        text = "".join(run.text[i] for i in indices).strip()
        if text and text not in covered:
            covered.append(text)
    return covered


def covered_strings_for_regions(
    runs: list[TextRun], regions: list[RedactionRegion]
) -> list[str]:
    """Union of covered strings across every region, longest first.

    Longer strings are scrubbed before shorter ones so a substring match never
    eats half of a longer secret and leaves the rest behind.
    """

    seen: list[str] = []
    for region in regions:
        for text in covered_strings_for_region(runs, region):
            if text not in seen:
                seen.append(text)
    seen.sort(key=len, reverse=True)
    return seen


def region_page_text(runs: list[TextRun], region: RedactionRegion) -> str:
    """Convenience: the covered text for a single region as one string."""

    page_runs = [r for r in runs if r.page_number == region.page_number]
    return covered_text_for_region(page_runs, region.box)


def regions_by_page(regions: list[RedactionRegion]) -> dict[int, list[RedactionRegion]]:
    grouped: dict[int, list[RedactionRegion]] = {}
    for region in regions:
        grouped.setdefault(region.page_number, []).append(region)
    return grouped

