from __future__ import annotations

"""Dictionary views of a document and a redaction result."""

from document import PdfDocument
from redaction_models import Annotation, RedactionResult


def annotation_to_dict(annotation: Annotation) -> dict[str, object]:
    return {
        "annotation_id": annotation.annotation_id,
        "kind": annotation.kind,
        "page_number": annotation.page_number,
        "box": list(annotation.box.as_tuple()),
        "label": annotation.label,
    }


def document_to_dict(document: PdfDocument) -> dict[str, object]:
    pages: list[dict[str, object]] = []
    for number in document.page_numbers():
        page = document.page(number)
        pages.append(
            {
                "page_number": number,
                "run_ids": page.run_ids(),
                "text": page.text(),
                "annotation_ids": [a.annotation_id for a in page.annotations],
            }
        )
    return {
        "doc_id": document.doc_id,
        "page_count": document.page_count(),
        "metadata": document.get_metadata(),
        "bookmarks": [
            {"title": b.title, "page_number": b.page_number}
            for b in document.bookmarks
        ],
        "attachments": [
            {"name": a.name, "text_content": a.text_content}
            for a in document.attachments
        ],
        "pages": pages,
        "extracted_text": document.extract_text(),
    }


def result_to_dict(result: RedactionResult) -> dict[str, object]:
    payload: dict[str, object] = {
        "regions_applied": result.regions_applied,
        "runs_removed": result.runs_removed,
        "runs_split": result.runs_split,
        "marks_added": result.marks_added,
        "metadata_scrubbed": result.metadata_scrubbed,
        "bookmarks_scrubbed": result.bookmarks_scrubbed,
        "attachments_scrubbed": result.attachments_scrubbed,
        "content_edits": result.total_content_edits(),
    }
    payload.update(result.details)
    return payload


def metadata_contains(document: PdfDocument, needle: str) -> bool:
    """True when ``needle`` appears anywhere in the metadata fields."""

    meta = document.get_metadata()
    haystacks = [meta["title"], meta["author"], meta["subject"]]
    haystacks.extend(meta["keywords"])
    return any(needle in str(value) for value in haystacks)


def attachments_contain(document: PdfDocument, needle: str) -> bool:
    return any(needle in body for body in document.attachment_text())


def bookmarks_contain(document: PdfDocument, needle: str) -> bool:
    return any(needle in title for title in document.bookmark_titles())

